(function() {

  var header    = document.querySelector('h1');
  var selectBox = document.querySelector('select');
  var runButton = document.querySelector('button');

  // On SelectBox Change
  selectBox.addEventListener('change', function() {
    triggerAnimation();
  })

  // On "run animation" button clicked
  runButton.addEventListener('click', function(e) {
    e.preventDefault();
    triggerAnimation();
  })

  function triggerAnimation() {

    var animation = selectBox.value;
    header.className = "";
    setTimeout(function() {
      header.className = "animated " + animation;
    }, 10);

  }

})();

/*
 * Obnoxious.CSS Demo Site
 */

html {
  height: 100%;
}

body {
  height: 100%;
  margin: 0px;
}

.center {
  font-family: 'Montserrat', sans-serif;
  transform: translateY(-50%);
  text-align: center;
  position: fixed;
  margin: 0px;
  width: 100%;
  color: #222;
  z-index: 1;
  top: 50%;
}

.center h1 {
  font-size: 70px;
  position: relative;
  margin: 0px;
}

.center .description {
  font-family: monospace;
  line-height: 22px;
  font-size: 18px;
  width: 370px;
  margin: auto;
  margin-top: 10px;
  margin-bottom: 25px;
}

.select {
  display: inline-block;
  margin-right: 10px;
  position: relative;
}

select {
  transition: background-color 200ms ease;
  font-size: 14px;
  padding: 10px;
  -webkit-appearance: none;
  -moz-appearance: none;
  appearance: none;
  box-sizing: border-box;
  border-radius: 3px;
  font-family: monospace;
  padding-right: 30px;
  position: relative;
  outline: 0px;
  background: #fff;
  cursor: pointer;
}

.select:after {
  content: "▼";
  padding: 14px 8px;
  position: absolute;
  right: 13px;
  top: 0;
  z-index: 1;
  text-align: center;
  width: 10%;
  height: 100%;
  pointer-events: none;
  box-sizing: border-box;
  font-size: 9px;
}

button {
  transition: background-color 200ms ease;
  font-size: 14px;
  padding: 10px 12px;
  -webkit-appearance: none;
  -moz-appearance: none;
  appearance: none;
  box-sizing: border-box;
  border-radius: 3px;
  border: 1px solid #aaa;
  background: #fff;
  font-family: monospace;
  cursor: pointer;
  outline: 0px;
}

button:hover,
select:hover {
  background-color: #eee;
}

.center .links {
  padding-top: 60px;
  font-family: monospace;
  letter-spacing: 0.3px;
  font-style: italic;
  font-size: 14px;
}

.center .links a {
  text-decoration: none;
  margin-left: 10px;
  margin-right: 10px;
  color: #777;
}

.center .links a:hover {
  text-decoration: underline;
}

iframe {
  margin-left: 14px;
  margin-bottom: -5px;
}


@media (max-width: 900px) {

  .center h1 {
    font-size: 50px;
  }

  .center .links a, .center .links iframe {
    display: block;
    margin: auto;
    margin-bottom: 12px;
  }

  .divider {
    display: none;
  }
}

@media (max-width: 400px) {

  .center h1 {
    font-size: 26px;
  }

  .center .description {
    font-size: 14px;
    width: 100%;
    padding-left: 40px;
    padding-right: 40px;
    box-sizing: border-box;
  }

}
